    preferences JSONB
);
```

**UserProfiles Table (for personalization):**
```sql
CREATE TABLE user_profiles (
    profile_id UUID PRIMARY KEY,
    user_id UUID REFERENCES users(user_id) ON DELETE CASCADE,
    role VARCHAR(100),
    domain_context VARCHAR(100),
    communication_channel VARCHAR(100),
    relationship_context VARCHAR(100),
    complexity_level VARCHAR(100),
    -- Embeddings of user's writing style for personalization
    writing_style_embedding VECTOR(1536) -- Example dimension for OpenAI embeddings
);
```

**SavedDrafts Table (Optional, with consent):**
```sql
CREATE TABLE saved_drafts (
    draft_id UUID PRIMARY KEY,
    user_id UUID REFERENCES users(user_id) ON DELETE CASCADE,
    content TEXT NOT NULL,
    document_type VARCHAR(100),
    audience VARCHAR(100),
    writing_goal VARCHAR(100),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);
```

**Vector Database Schema (Conceptual - managed by Pinecone/Chroma):**
*   **Collection:** `user_writing_context`
*   **Fields:** `user_id`, `document_id`, `text_chunk`, `embedding` (vector)
*   **Purpose:** Store embeddings of user's past writing or relevant context for retrieval.

