    from fastapi import FastAPI, HTTPException, Request
    from fastapi.responses import StreamingResponse
    import uvicorn
    import os
    import openai
    import anthropic
    import redis
    from dotenv import load_dotenv
    from typing import Dict, Any, Optional
    import json

    load_dotenv()

    app = FastAPI()

    # Initialize AI clients
    openai.api_key = os.getenv("OPENAI_API_KEY")
    anthropic_client = anthropic.Anthropic(api_key=os.getenv("ANTHROPIC_API_KEY"))

    # Initialize Redis client
    redis_client = redis.Redis(host=os.getenv("REDIS_HOST", "localhost"), port=int(os.getenv("REDIS_PORT", 6379)), db=0)

    # Placeholder for Vector DB client (e.g., Pinecone)
    # import pinecone
    # pinecone.init(api_key=os.getenv("VECTOR_DB_API_KEY"), environment=os.getenv("VECTOR_DB_ENV"))
    # vector_db_index = pinecone.Index(os.getenv("VECTOR_DB_INDEX_NAME"))

    @app.post("/analyze")
    async def analyze_text(request: Request):
        data = await request.json()
        text = data.get("text")
        context = data.get("context", {{}})

        if not text:
            raise HTTPException(status_code=400, detail="Text is required")

        try:
            # Construct prompt for analysis
            prompt = construct_analysis_prompt(text, context)

            # Use LLM for analysis (e.g., OpenAI GPT-4)
            response = openai.ChatCompletion.create(
                model="gpt-4", # Or a suitable model
                messages=[
                    {"role": "system", "content": "You are an expert writing assistant. Analyze the provided text based on the given context."},
                    {"role": "user", "content": prompt}
                ],
                temperature=0.7,
                max_tokens=500
            )
            analysis_results = json.loads(response.choices[0].message.content)
            return analysis_results
        except Exception as e:
            print(f"Error during analysis: {e}")
            raise HTTPException(status_code=500, detail="Failed to analyze text")

    @app.post("/rewrite")
    async def rewrite_text(request: Request):
        data = await request.json()
        text = data.get("text")
        context = data.get("context", {{}})
        rewrite_type = data.get("rewrite_type", "professional") # e.g., 'concise', 'detailed', 'professional'

        if not text:
            raise HTTPException(status_code=400, detail="Text is required")

        try:
            # Construct prompt for rewriting
            prompt = construct_rewrite_prompt(text, context, rewrite_type)

            # Use LLM for rewriting (e.g., Anthropic Claude)
            # For streaming, use stream=True and handle chunks
            response = anthropic_client.messages.create(
                model="claude-3-opus-20240229", # Or a suitable model
                max_tokens=2000,
                temperature=0.7,
                messages=[
                    {"role": "user", "content": prompt}
                ]
            )
            rewritten_text = response.content[0].text
            return {"rewritten_text": rewritten_text}
        except Exception as e:
            print(f"Error during rewriting: {e}")
            raise HTTPException(status_code=500, detail="Failed to rewrite text")

    # Helper functions for prompt construction
    def construct_analysis_prompt(text: str, context: Dict[str, Any]) -> str:
        # Dynamically build prompt based on context parameters
        prompt_parts = [f"Analyze the following text:\n\n{text}\n\nContext:\n"]
        for key, value in context.items():
            if value is not None and value != '':
                prompt_parts.append(f"- {key.replace('_', ' ').title()}: {value}")
        prompt_parts.append("\nProvide a structured analysis including suggestions for clarity, conciseness, audience appropriateness, and goal alignment. Output should be in JSON format.")
        return "\n".join(prompt_parts)

    def construct_rewrite_prompt(text: str, context: Dict[str, Any], rewrite_type: str) -> str:
        # Dynamically build prompt for rewriting
        prompt_parts = [f"Rewrite the following text to be {rewrite_type} for the specified context:\n\n{text}\n\nContext:\n"]
        for key, value in context.items():
            if value is not None and value != '':
                prompt_parts.append(f"- {key.replace('_', ' ').title()}: {value}")
        prompt_parts.append("\nEnsure the rewritten text is natural, human-like, and avoids AI detection patterns. Focus on maintaining the original intent.")
        return "\n".join(prompt_parts)

    # Add more endpoints for other AI features (e.g., summarization, tone adjustment)

    if __name__ == "__main__":
        uvicorn.run(app, host="0.0.0.0", port=8000)
